+    fn owed_done(&mut self) -> Vec<Bytes> {
+        let Some(o) = self.owed.take() else { return Vec::new() };
+        self.closed.insert(o.index);
+        vec![event_frame(&done_event(o.index, &o.notice, o.seq.as_ref()))]
