1151	+impl Protocol for ResponsesStream {
1152	+    fn step(&mut self, rec: Record, _verdicts: &Verdicts) -> Result<Step, StepError> {
1153	+        // R3: after the terminal event only `[DONE]` may follow. Checked first, so a malformed
1154	+        // late record cannot become a failure either.
1155	+        if self.asm.ended() && rec.data != b"[DONE]" {
1156	+            return Err(StepError::AfterEnd);
1157	+        }
1158	+        let (ty, value) = match classify(&rec)? {
1159	+            Event::Done => {
1160	+                return Ok(Step::End(Frame {
1161	+                    event: None,
1162	+                    payload: rec.data,
1163	+                    value: None,
1164	+                    touches: Vec::new(),
1165	+                }));
1166	+            }
1167	+            Event::UpstreamError(value) => {
1168	+                return Ok(Step::UpstreamError(Frame {
1169	+                    event: None,
1170	+                    payload: rec.data,
1171	+                    value: Some(value),
1172	+                    touches: Vec::new(),
1173	+                }));
1174	+            }
1175	+            Event::Known { ty, value } => (ty, value),
1176	+        };
1177	+        let effect = self.asm.accept(ty, &value)?;
1178	+        // The terminal frame carries the hold's calls in `output`, once the hold has opened.
1179	+        let holds = effect.item.is_some() || (effect.terminal && self.asm.hold_open());
1180	+        let touches = if holds { vec![HoldKey::Response] } else { Vec::new() };
1181	+        let frame = Frame {
1182	+            event: Some(ty),
1183	+            payload: rec.data,
1184	+            value: Some(value),
1185	+            touches,
1186	+        };
1187	+        if effect.terminal {
1188	+            let mut completed = Vec::new();
1189	+            if self.asm.hold_open() && !self.asm.hold_cut() {
1190	+                self.completed = true;
1191	+                completed.push((HoldKey::Response, self.asm.hold_calls()));
1192	+            }
1193	+            return Ok(Step::Terminal { frame, completed });
1194	+        }
1195	+        Ok(Step::Frame {
1196	+            frame,
1197	+            opened: if effect.opened { vec![HoldKey::Response] } else { Vec::new() },
1198	+            completed: Vec::new(),
1199	+            reports: effect.report.into_iter().collect(),
1200	+        })
1201	+    }
1202	+
1203	+    fn incomplete(&self) -> Vec<HoldKey> {
1204	+        if self.asm.hold_cut() && !self.completed { vec![HoldKey::Response] } else { Vec::new() }
1205	+    }
1206	+
1207	+    fn release(&mut self, frame: Frame, verdicts: &Verdicts) -> Vec<Bytes> {
1208	+        let Some(value) = frame.value else {
1209	+            let mut out = self.owed_done();
1210	+            out.push(sse::frame(None, &frame.payload));
1211	+            return out;
1212	+        };
1213	+        let original = || sse::frame(event_of(&value), &frame.payload);
1214	+        let verdict = verdicts.get(&HoldKey::Response).filter(|v| v.blocks_any());
1215	+        if !frame.touches.contains(&HoldKey::Response) {
1216	+            // A keepalive or a response-level event may sit inside an item (R5 is about items);
1217	+            // any other frame here ends the open item: an upstream error record.
1218	+            let inside = frame.event.map(scope_of).is_some_and(|s| matches!(s, Scope::Keepalive | Scope::ResponseLevel));
1219	+            let mut out = if inside { Vec::new() } else { self.owed_done() };
1220	+            out.push(original());
1221	+            return out;
1222	+        }
1223	+        let Some(verdict) = verdict else { return vec![original()] };
1224	+        if frame.event.map(scope_of) == Some(Scope::Terminal) {
1225	+            let mut out = self.owed_done();
1226	+            out.push(match self.rewrite_terminal(&value, verdict) {
1227	+                Some(v) => event_frame(&v),
1228	+                None => original(),
1229	+            });
1230	+            return out;
1231	+        }
1232	+        let index = value.get("output_index").and_then(Value::as_u64).and_then(|i| u32::try_from(i).ok());
1233	+        let blocked = index.and_then(|i| self.asm.slot_of(i).map(|s| (i, s))).and_then(|(i, s)| verdict.block_code(s).map(|c| (i, s, c)));
1234	+        match blocked {
1235	+            Some((i, slot, code)) => self.rewrite_item(&value, i, slot, code),
1236	+            None => vec![original()],
1237	+        }
1238	+    }
1239	+
1240	+    fn closing(&mut self, _verdicts: &Verdicts) -> Vec<Bytes> {
1241	+        self.owed_done()
1242	+    }
1243	+
1244	+    fn closing_on_abort(&mut self, _verdicts: &Verdicts) -> Vec<Bytes> {
1245	+        self.owed_done()
1246	+    }
