1384	+    /// Step every record, give each completed hold `verdict` and each cut hold `BlockAll(cut)`,
1385	+    /// release every frame, then close. Returns the output, the decided calls and the stream.
1386	+    fn run(records: &[Record], verdict: impl Fn(&[ToolCall]) -> Verdict, cut: BlockCode) -> (String, Vec<ToolCall>, ResponsesStream) {
1387	+        let mut p = ResponsesStream::with_cap(1 << 20);
1388	+        let mut verdicts = Verdicts::new();
1389	+        let mut frames = Vec::new();
1390	+        let mut calls = Vec::new();
