1396	+                        calls.extend(c);
1397	+                    }
1398	+                    for k in p.incomplete() {
1399	+                        verdicts.entry(k).or_insert(Verdict::BlockAll(cut));
1400	+                    }
1401	+                    frames.push(frame);
1402	+                }
1403	+                Step::Frame { frame, .. } | Step::End(frame) | Step::UpstreamError(frame) => frames.push(frame),
1404	+            }
