+        for (pos, name) in [(0, "read"), (1, "rm")] {
+            assert!(out.contains(&format!(r#""position":{pos},"name":"{name}""#)), "{out}");
+            assert!(out.contains(&format!(r#"tool call \"{name}\" was blocked (truncated)."#)), "{out}");
+            assert!(out.contains(&format!("msg_paigasus_{pos}")), "{out}");
